import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"Fibers & blocking→async","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/fibers-and-blocking-to-async.md","filePath":"deep-dive/fibers-and-blocking-to-async.md"}'),o={name:"deep-dive/fibers-and-blocking-to-async.md"};function n(r,e,c,l,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="fibers-blocking→async" tabindex="-1">Fibers &amp; blocking→async <a class="header-anchor" href="#fibers-blocking→async" aria-label="Permalink to &quot;Fibers &amp; blocking→async&quot;">​</a></h1><p>This is the headline RUSM (and Lunatic) property: <strong>a guest writes ordinary blocking code, and the runtime turns every blocking call into an async suspension.</strong> Guests never write <code>async</code>, never juggle futures, never color a function — yet a million &quot;blocked&quot; processes cost almost nothing. Here&#39;s the trick that makes it work.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Wasmtime&#39;s <strong>async support</strong> runs each instance on its own <strong>fiber</strong> — a separate call stack. When a guest calls a host function that is <code>async</code> on the Rust side — say <code>receive()</code> waiting on an empty mailbox — the host <code>await</code>s, and Wasmtime <strong>suspends the guest&#39;s entire call stack</strong> by switching off the fiber. The Tokio task yields, the OS thread picks up another process, and when the await resolves Wasmtime switches the fiber back in. The guest call simply returns, none the wiser that it was ever parked.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><ul><li><strong>Simpler guests.</strong> No <code>async</code>/<code>await</code> noise anywhere in your code — and you can call blocking C libraries compiled to Wasm without ever blocking a real thread.</li><li><strong>Massive concurrency.</strong> A &quot;blocked&quot; process is just a parked task, so millions of them fit on a few OS threads. This is what makes process-per-request and process-per-connection serving cheap.</li></ul><h2 id="relation-to-lunatic-s-stack-switching" tabindex="-1">Relation to Lunatic&#39;s stack switching <a class="header-anchor" href="#relation-to-lunatic-s-stack-switching" aria-label="Permalink to &quot;Relation to Lunatic&#39;s stack switching&quot;">​</a></h2><p>Lunatic cites a libfringe-inspired custom stack switcher. Wasmtime&#39;s fiber support is the same idea — stack switching — but battle-tested and memory-safe, so RUSM builds on it rather than hand-rolling its own. For <em>fair</em> scheduling on top of this — so a guest that never makes a host call still can&#39;t hog a thread — see <a href="/rusm/deep-dive/epoch-preemption">epoch preemption</a>.</p><blockquote><p>Shipped in Phase 6 (the Wasmtime backend).</p></blockquote>',9)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
